import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry matmul_tiled(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    .reg .pred pA, pB, pRowIn, pColIn, pKAIn, pKBIn, pLoopEnd, pStore, pSingle, pNext, pKAIn2, pKBIn2, pCopyThread, pFullCur, pFullNext, pRowOkVec, pColOkVec, pVecA, pVecB, pRowOkVec2, pColOkVec2, pVecA2, pVecB2, pKAligned, pLane0, pKLoop;
    .reg .f32 acc, a, b, z;
    .reg .u32 rM, rN, rK, rBx, rBy, rBz, rGz, rTx, rTy, rRow, rCol, rKbase, rKidxA, rKidxB, rk, idx32, tCopy, rKslice, rKstart, rKend, tmp32, rKnext, rRowBase, rColBase, rRowTile, rVecCol, rKvec, rRowGlob, rColGlob, rV4, rLane;
    .reg .u64 A, B, C, gA, gB, gC, off64, baseSA, baseSB, baseSA1, baseSB1, SAcur, SBcur, SAnext, SBnext, offA, offB, idx64, tmp64, offS;
    .shared .align 16 .b8 sA[8192];
    .shared .align 16 .b8 sB[8192];
    // Load parameters
    ld.param.u64 A, [A_ptr];
    ld.param.u64 B, [B_ptr];
    ld.param.u64 C, [C_ptr];
    ld.param.u32 rM, [M];
    ld.param.u32 rN, [N];
    ld.param.u32 rK, [K];
    // Convert to global addresses
    cvta.to.global.u64 gA, A;
    cvta.to.global.u64 gB, B;
    cvta.to.global.u64 gC, C;
    // Thread and block indices
    mov.u32 rTx, %tid.x;
    mov.u32 rTy, %tid.y;
    mov.u32 rBx, %ctaid.x;
    mov.u32 rBy, %ctaid.y;
    mov.u32 rBz, %ctaid.z;
    mov.u32 rGz, %nctaid.z;
    // Compute output row and column
    mad.lo.u32 rRow, rBy, 32, rTy;
    mad.lo.u32 rCol, rBx, 32, rTx;
    // Compute block base row/col
    mul.lo.u32 rRowBase, rBy, 32;
    mul.lo.u32 rColBase, rBx, 32;
    // Predicates for bounds
    setp.lt.u32 pRowIn, rRow, rM;
    setp.lt.u32 pColIn, rCol, rN;
    // Shared memory base pointers and double-buffer setup
    mov.u64 baseSA, sA;
    mov.u64 baseSB, sB;
    add.u64 baseSA1, baseSA, 4096;
    add.u64 baseSB1, baseSB, 4096;
    mov.u64 SAcur, baseSA;
    mov.u64 SBcur, baseSB;
    mov.u64 SAnext, baseSA1;
    mov.u64 SBnext, baseSB1;
    // Initialize accumulator
    mov.f32 acc, 0f00000000;
    mov.f32 z, 0f00000000;
    // Compute Split-K slice [rKstart, rKend)
    add.u32 tmp32, rK, rGz;
    sub.u32 tmp32, tmp32, 1;
    div.u32 rKslice, tmp32, rGz;       // ceil_div(rK, rGz)
    mul.lo.u32 rKstart, rBz, rKslice;  // start = bz * slice
    add.u32 rKend, rKstart, rKslice;   // end = start + slice
    setp.gt.u32 pLoopEnd, rKend, rK;
    @pLoopEnd mov.u32 rKend, rK;       // clamp to K
    mov.u32 rKbase, rKstart;
    // Precompute per-thread shared offset within a tile and permanent copy id
    mad.lo.u32 idx32, rTy, 32, rTx;   // idx = ty*32 + tx
    mov.u32 tCopy, idx32;             // permanent copy-lane id
    mul.wide.u32 offS, idx32, 4;
    // Lane id for warp-level broadcast of A
    mov.u32 rLane, %laneid;
    setp.eq.u32 pLane0, rLane, 0;
    // If no tiles in slice, skip to store
    setp.ge.u32 pLoopEnd, rKbase, rKend;
    @pLoopEnd bra AfterTiles;
    // Prefetch current tile (rKbase) into SAcur/SBcur using cp.async
    // Use 16B vectorized copies when full K tile available, otherwise fallback to scalar 4B copies
    add.u32 tmp32, rKbase, 32;
    setp.le.u32 pFullCur, tmp32, rKend; // full 32-wide tile fits in slice
    and.b32 tmp32, rK, 3;               // compute K % 4
    setp.eq.u32 pKAligned, tmp32, 0;    // K divisible by 4 => 16B global alignment
    and.pred pFullCur, pFullCur, pKAligned; // require K%4==0 for 16B vector path
    setp.lt.u32 pCopyThread, tCopy, 256; // 256 threads perform 16B copies
    @!pFullCur bra ScalarPrefetchCur;
VectorPrefetchCur:
    // Compute per-copy coordinates
    shr.u32 rRowTile, tCopy, 3;       // row in tile [0..31]
    and.b32 rVecCol, tCopy, 7;        // vector column group [0..7]
    shl.b32 rV4, rVecCol, 2;          // 4 * vecCol
    // A: rows over M, columns over K
    add.u32 rRowGlob, rRowBase, rRowTile;
    setp.lt.u32 pRowOkVec, rRowGlob, rM;
    shl.b32 rKvec, rVecCol, 2;        // 4 * vecCol
    add.u32 rKvec, rKbase, rKvec;
    // Shared dest offset for A
    mad.lo.u32 tmp32, rRowTile, 32, rV4;
    shl.b32 tmp32, tmp32, 2;          // bytes offset within tile for start of 4-wide vec
    // Actually cp.async size handles 16B contiguous, dest addr is element base
    // Build shared address for A
    cvt.u64.u32 offA, tmp32;
    add.u64 offA, SAcur, offA;
    // Global address for A
    mul.wide.u32 idx64, rRowGlob, rK; // row * K
    cvt.u64.u32 tmp64, rKvec;
    add.u64 idx64, idx64, tmp64;      // row*K + k_base_vec
    shl.b64 off64, idx64, 2;          // *4 bytes
    add.u64 off64, gA, off64;
    and.pred pVecA, pCopyThread, pRowOkVec;
    @pVecA cp.async.ca.shared.global [offA], [off64], 16;
    // B: rows over K, columns over N
    add.u32 rColGlob, rColBase, rV4;     // N-dim 4-wide vector base
    add.u32 rRowGlob, rKbase, rRowTile;  // rRowGlob now k index
    add.u32 tmp32, rColGlob, 3;
    setp.lt.u32 pColOkVec, tmp32, rN;    // col_base+3 < N
    // Shared dest offset for B (same tile layout)
    mad.lo.u32 tmp32, rRowTile, 32, rV4;
    shl.b32 tmp32, tmp32, 2;
    cvt.u64.u32 offB, tmp32;
    add.u64 offB, SBcur, offB;
    // Global address for B
    mul.wide.u32 idx64, rRowGlob, rN; // k * N
    cvt.u64.u32 tmp64, rColGlob;
    add.u64 idx64, idx64, tmp64;      // k*N + col_base_vec
    shl.b64 off64, idx64, 2;          // *4 bytes
    add.u64 off64, gB, off64;
    and.pred pVecB, pCopyThread, pColOkVec;
    @pVecB cp.async.ca.shared.global [offB], [off64], 16;
    cp.async.commit_group;
    bra PrefetchCurDone;
ScalarPrefetchCur:
    // Fallback: scalar 4B copies with per-element predicates
    // A[row, kIdxA]
    add.u32 rKidxA, rKbase, rTx;
    mul.wide.u32 idx64, rRow, rK;   // row * K
    cvt.u64.u32 tmp64, rKidxA;
    add.u64 idx64, idx64, tmp64;    // row*K + kIdxA
    shl.b64 off64, idx64, 2;        // *4 bytes
    add.u64 off64, gA, off64;
    setp.lt.u32 pKAIn, rKidxA, rKend;
    and.pred pA, pRowIn, pKAIn;
    add.u64 offA, SAcur, offS;
    @pA cp.async.ca.shared.global [offA], [off64], 4;
    // B[kIdxB, col]
    add.u32 rKidxB, rKbase, rTy;
    mul.wide.u32 idx64, rKidxB, rN; // kIdxB * N
    cvt.u64.u32 tmp64, rCol;
    add.u64 idx64, idx64, tmp64;    // kIdxB*N + col
    shl.b64 off64, idx64, 2;        // *4 bytes
    add.u64 off64, gB, off64;
    setp.lt.u32 pKBIn, rKidxB, rKend;
    and.pred pB, pColIn, pKBIn;
    add.u64 offB, SBcur, offS;
    @pB cp.async.ca.shared.global [offB], [off64], 4;
    cp.async.commit_group;
PrefetchCurDone:
    // Prefetch next tile (rKbase+32) into SAnext/SBnext if exists
    add.u32 rKnext, rKbase, 32;
    setp.lt.u32 pNext, rKnext, rKend;
    @!pNext bra SkipPrefetchNextInit;
        // If full tile available for next, use vectorized 16B copies
        add.u32 tmp32, rKnext, 32;
        setp.le.u32 pFullNext, tmp32, rKend;
        and.b32 tmp32, rK, 3;               // compute K % 4
        setp.eq.u32 pKAligned, tmp32, 0;    // K divisible by 4
        and.pred pFullNext, pFullNext, pKAligned;
        @!pFullNext bra ScalarPrefetchNextInit;
VectorPrefetchNextInit:
        // Compute per-copy coordinates
        shr.u32 rRowTile, tCopy, 3;
        and.b32 rVecCol, tCopy, 7;
        shl.b32 rV4, rVecCol, 2;          // 4 * vecCol
        // A next
        add.u32 rRowGlob, rRowBase, rRowTile;
        setp.lt.u32 pRowOkVec2, rRowGlob, rM;
        shl.b32 rKvec, rVecCol, 2;
        add.u32 rKvec, rKnext, rKvec;
        mad.lo.u32 tmp32, rRowTile, 32, rV4;
        shl.b32 tmp32, tmp32, 2;
        cvt.u64.u32 offA, tmp32;
        add.u64 offA, SAnext, offA;
        mul.wide.u32 idx64, rRowGlob, rK;
        cvt.u64.u32 tmp64, rKvec;
        add.u64 idx64, idx64, tmp64;
        shl.b64 off64, idx64, 2;
        add.u64 off64, gA, off64;
        and.pred pVecA2, pCopyThread, pRowOkVec2;
        @pVecA2 cp.async.ca.shared.global [offA], [off64], 16;
        // B next
        add.u32 rColGlob, rColBase, rV4;
        add.u32 rRowGlob, rKnext, rRowTile;
        add.u32 tmp32, rColGlob, 3;
        setp.lt.u32 pColOkVec2, tmp32, rN;
        mad.lo.u32 tmp32, rRowTile, 32, rV4;
        shl.b32 tmp32, tmp32, 2;
        cvt.u64.u32 offB, tmp32;
        add.u64 offB, SBnext, offB;
        mul.wide.u32 idx64, rRowGlob, rN;
        cvt.u64.u32 tmp64, rColGlob;
        add.u64 idx64, idx64, tmp64;
        shl.b64 off64, idx64, 2;
        add.u64 off64, gB, off64;
        and.pred pVecB2, pCopyThread, pColOkVec2;
        @pVecB2 cp.async.ca.shared.global [offB], [off64], 16;
        cp.async.commit_group;
        bra AfterPrefetchNextInit;
ScalarPrefetchNextInit:
        // Fallback scalar copies for next tile
        // A[row, kIdxA_next]
        add.u32 rKidxA, rKnext, rTx;
        mul.wide.u32 idx64, rRow, rK;
        cvt.u64.u32 tmp64, rKidxA;
        add.u64 idx64, idx64, tmp64;
        shl.b64 off64, idx64, 2;
        add.u64 off64, gA, off64;
        setp.lt.u32 pKAIn2, rKidxA, rKend;
        and.pred pKAIn2, pKAIn2, pRowIn;
        add.u64 offA, SAnext, offS;
        @pKAIn2 cp.async.ca.shared.global [offA], [off64], 4;
        // B[kIdxB_next, col]
        add.u32 rKidxB, rKnext, rTy;
        mul.wide.u32 idx64, rKidxB, rN;
        cvt.u64.u32 tmp64, rCol;
        add.u64 idx64, idx64, tmp64;
        shl.b64 off64, idx64, 2;
        add.u64 off64, gB, off64;
        setp.lt.u32 pKBIn2, rKidxB, rKend;
        and.pred pKBIn2, pKBIn2, pColIn;
        add.u64 offB, SBnext, offS;
        @pKBIn2 cp.async.ca.shared.global [offB], [off64], 4;
        cp.async.commit_group;
AfterPrefetchNextInit:
SkipPrefetchNextInit:
    // Wait for current (and possibly next) copies to complete before using current tile
    @pNext cp.async.wait_group 1;
    @!pNext cp.async.wait_group 0;
    bar.sync 0;
    // Zero-fill out-of-bounds lanes for current tile in shared memory
    add.u64 offA, SAcur, offS;
    add.u64 offB, SBcur, offS;
    // Recompute scalar predicates for this thread for zero fill
    add.u32 rKidxA, rKbase, rTx;
    setp.lt.u32 pKAIn, rKidxA, rKend;
    and.pred pA, pRowIn, pKAIn;
    add.u32 rKidxB, rKbase, rTy;
    setp.lt.u32 pKBIn, rKidxB, rKend;
    and.pred pB, pColIn, pKBIn;
    @!pA st.shared.f32 [offA], z;
    @!pB st.shared.f32 [offB], z;
    // Compute on current tile with warp-level broadcast of A
    mov.u32 rk, 0;
ComputeCurK:
    mad.lo.u32 idx32, rTy, 32, rk;
    mul.wide.u32 offA, idx32, 4;
    add.u64 offA, SAcur, offA;
    @pLane0 ld.shared.f32 a, [offA];
    shfl.sync.idx.b32 a, a, 0, 0x1f, 0xffffffff;
    mad.lo.u32 idx32, rk, 32, rTx;
    mul.wide.u32 offB, idx32, 4;
    add.u64 offB, SBcur, offB;
    ld.shared.f32 b, [offB];
    fma.rn.f32 acc, a, b, acc;
    add.u32 rk, rk, 1;
    setp.lt.u32 pKLoop, rk, 32;
    @pKLoop bra ComputeCurK;
    // Ensure all threads finished reading current buffer before it may be reused
    bar.sync 0;
LoopTiles:
    // If no next tile, finish
    @!pNext bra AfterTiles;
    // Swap current and next buffers
    mov.u64 tmp64, SAcur;
    mov.u64 SAcur, SAnext;
    mov.u64 SAnext, tmp64;
    mov.u64 tmp64, SBcur;
    mov.u64 SBcur, SBnext;
    mov.u64 SBnext, tmp64;
    // Advance K base
    mov.u32 rKbase, rKnext;
    // Prefetch following tile (rKbase+32) into SAnext/SBnext if exists
    add.u32 rKnext, rKbase, 32;
    setp.lt.u32 pNext, rKnext, rKend;
    @!pNext bra AfterPrefetchNextLoop;
        add.u32 tmp32, rKnext, 32;
        setp.le.u32 pFullNext, tmp32, rKend;
        and.b32 tmp32, rK, 3;               // compute K % 4
        setp.eq.u32 pKAligned, tmp32, 0;    // K divisible by 4
        and.pred pFullNext, pFullNext, pKAligned;
        @!pFullNext bra ScalarPrefetchNextLoop;
VectorPrefetchNextLoop:
        // Vectorized 16B copies for next loop tile
        shr.u32 rRowTile, tCopy, 3;
        and.b32 rVecCol, tCopy, 7;
        shl.b32 rV4, rVecCol, 2;          // 4 * vecCol
        // A next
        add.u32 rRowGlob, rRowBase, rRowTile;
        setp.lt.u32 pRowOkVec2, rRowGlob, rM;
        shl.b32 rKvec, rVecCol, 2;
        add.u32 rKvec, rKnext, rKvec;
        mad.lo.u32 tmp32, rRowTile, 32, rV4;
        shl.b32 tmp32, tmp32, 2;
        cvt.u64.u32 offA, tmp32;
        add.u64 offA, SAnext, offA;
        mul.wide.u32 idx64, rRowGlob, rK;
        cvt.u64.u32 tmp64, rKvec;
        add.u64 idx64, idx64, tmp64;
        shl.b64 off64, idx64, 2;
        add.u64 off64, gA, off64;
        and.pred pVecA2, pCopyThread, pRowOkVec2;
        @pVecA2 cp.async.ca.shared.global [offA], [off64], 16;
        // B next
        add.u32 rColGlob, rColBase, rV4;
        add.u32 rRowGlob, rKnext, rRowTile;
        add.u32 tmp32, rColGlob, 3;
        setp.lt.u32 pColOkVec2, tmp32, rN;
        mad.lo.u32 tmp32, rRowTile, 32, rV4;
        shl.b32 tmp32, tmp32, 2;
        cvt.u64.u32 offB, tmp32;
        add.u64 offB, SBnext, offB;
        mul.wide.u32 idx64, rRowGlob, rN;
        cvt.u64.u32 tmp64, rColGlob;
        add.u64 idx64, idx64, tmp64;
        shl.b64 off64, idx64, 2;
        add.u64 off64, gB, off64;
        and.pred pVecB2, pCopyThread, pColOkVec2;
        @pVecB2 cp.async.ca.shared.global [offB], [off64], 16;
        cp.async.commit_group;
        bra AfterPrefetchNextLoop;
ScalarPrefetchNextLoop:
        // Scalar fallback for next loop tile
        add.u32 rKidxA, rKnext, rTx;
        mul.wide.u32 idx64, rRow, rK;
        cvt.u64.u32 tmp64, rKidxA;
        add.u64 idx64, idx64, tmp64;
        shl.b64 off64, idx64, 2;
        add.u64 off64, gA, off64;
        setp.lt.u32 pKAIn2, rKidxA, rKend;
        and.pred pKAIn2, pKAIn2, pRowIn;
        add.u64 offA, SAnext, offS;
        @pKAIn2 cp.async.ca.shared.global [offA], [off64], 4;
        add.u32 rKidxB, rKnext, rTy;
        mul.wide.u32 idx64, rKidxB, rN;
        cvt.u64.u32 tmp64, rCol;
        add.u64 idx64, idx64, tmp64;
        shl.b64 off64, idx64, 2;
        add.u64 off64, gB, off64;
        setp.lt.u32 pKBIn2, rKidxB, rKend;
        and.pred pKBIn2, pKBIn2, pColIn;
        add.u64 offB, SBnext, offS;
        @pKBIn2 cp.async.ca.shared.global [offB], [off64], 4;
        cp.async.commit_group;
AfterPrefetchNextLoop:
    // Wait for current tile copies (issued previously) to complete before using
    @pNext cp.async.wait_group 1;
    @!pNext cp.async.wait_group 0;
    bar.sync 0;
    // Compute predicates for current tile (rKbase) to zero-fill OOB lanes
    add.u32 rKidxA, rKbase, rTx;
    setp.lt.u32 pKAIn, rKidxA, rKend;
    and.pred pA, pRowIn, pKAIn;
    add.u32 rKidxB, rKbase, rTy;
    setp.lt.u32 pKBIn, rKidxB, rKend;
    and.pred pB, pColIn, pKBIn;
    add.u64 offA, SAcur, offS;
    add.u64 offB, SBcur, offS;
    @!pA st.shared.f32 [offA], z;
    @!pB st.shared.f32 [offB], z;
    // Compute on current loop tile with warp-level broadcast of A
    mov.u32 rk, 0;
ComputeLoopK:
    mad.lo.u32 idx32, rTy, 32, rk;
    mul.wide.u32 offA, idx32, 4;
    add.u64 offA, SAcur, offA;
    @pLane0 ld.shared.f32 a, [offA];
    shfl.sync.idx.b32 a, a, 0, 0x1f, 0xffffffff;
    mad.lo.u32 idx32, rk, 32, rTx;
    mul.wide.u32 offB, idx32, 4;
    add.u64 offB, SBcur, offB;
    ld.shared.f32 b, [offB];
    fma.rn.f32 acc, a, b, acc;
    add.u32 rk, rk, 1;
    setp.lt.u32 pKLoop, rk, 32;
    @pKLoop bra ComputeLoopK;
    // Ensure all threads finished reading current buffer before it may be reused
    bar.sync 0;
    bra LoopTiles;
AfterTiles:
    // Store C[row, col] if within bounds
    and.pred pStore, pRowIn, pColIn;
    @!pStore bra StoreDone;
    mul.wide.u32 idx64, rRow, rN;  // row * N
    cvt.u64.u32 tmp64, rCol;
    add.u64 idx64, idx64, tmp64;   // row*N + col
    shl.b64 off64, idx64, 2;       // *4 bytes
    add.u64 off64, gC, off64;
    // Use atomicAdd for Split-K, plain store if no split (gridDim.z == 1)
    setp.eq.u32 pSingle, rGz, 1;
    @pSingle st.global.f32 [off64], acc;
    @!pSingle atom.global.add.f32 a, [off64], acc;
StoreDone:
    ret;
}
"""
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_tiled")
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        M = int(A.shape[0])
        K = int(A.shape[1])
        N = int(B.shape[1])
        module = _get_ptx_module()
        block_x = 32
        block_y = 32
        grid_x = (N + block_x - 1) // block_x
        grid_y = (M + block_y - 1) // block_y
        split_k = min(32, max(1, (K + 4095) // 4096))
        if split_k > 1:
            C = torch.zeros((M, N), device=A.device, dtype=A.dtype)
        else:
            C = torch.empty((M, N), device=A.device, dtype=A.dtype)
        module.launch(
            "matmul_tiled",
            grid=(grid_x, grid_y, split_k),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, i32(M), i32(N), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

