    .reg .f32 acc, a, b, z;
    .reg .u32 rM, rN, rK, rBx, rBy, rBz, rGz, rTx, rTy, rRow, rCol, rKbase, rKidxA, rKidxB, rk, idx32, tCopy, rKslice, rKstart, rKend, tmp32, rKnext, rRowBase, rColBase, rRowTile, rVecCol, rKvec, rRowGlob, rColGlob, rV4;
    .reg .u64 A, B, C, gA, gB, gC, off64, baseSA, baseSB, baseSA1, baseSB1, SAcur, SBcur, SAnext, SBnext, offA, offB, idx64, tmp64, offS;
